"""``dbs qc ...`` commands."""

from __future__ import annotations

import argparse
import sys
from pathlib import Path

from dynamisbench_soccer.qc.spec import RuleSet, Status, load, run, validate, verdict
from dynamisbench_soccer.registry.models import load as load_registry
from dynamisbench_soccer.signals import io

RULES = Path("qc/rules.toml")
SPEC_DOC = Path("docs/qc-rules.md")


def rules_markdown(rules: RuleSet) -> str:
    lines = [
        f"# QC rules v{rules.version}",
        "",
        "<!-- GENERATED by `dbs qc rules --write` from qc/rules.toml; do not edit by hand. -->",
        "",
        "Parameters are defaults. Tasks may override them and must say so. See "
        "[qc-spec.md](qc-spec.md) for semantics.",
        "",
        "| Id | Name | Level | Severity | Applies to | Claims | Default params |",
        "| -- | -- | -- | -- | -- | -- | -- |",
    ]
    for r in rules.rule:
        params = ", ".join(f"`{k}={v:g}`" for k, v in r.params.items()) or "-"
        claims = ", ".join(r.claims) or f"({r.basis})"
        lines.append(
            f"| {r.id} | `{r.name}` | {r.level} | {r.severity} | "
            f"{', '.join(r.applies_to)} | {claims} | {params} |"
        )
    lines += ["", "## Rationale", ""]
    lines += [f"* **{r.id} `{r.name}`**: {r.rationale}" for r in rules.rule]
    return "\n".join(lines) + "\n"


def _cmd_validate(args: argparse.Namespace) -> int:
    rules = load(Path(args.rules))
    problems = validate(rules, load_registry(Path(args.registry)))
    for p in problems:
        print(f"FAIL {p}", file=sys.stderr)
    print(f"qc: {len(rules.rule)} rules: {'OK' if not problems else f'{len(problems)} problem(s)'}")
    return 1 if problems else 0


def _cmd_rules(args: argparse.Namespace) -> int:
    text = rules_markdown(load(Path(args.rules)))
    target = Path(args.doc)
    if args.write:
        target.write_text(text, encoding="utf-8")
        print(f"wrote {target}")
    elif args.check:
        if not target.is_file() or target.read_text(encoding="utf-8") != text:
            print(f"FAIL {target} out of date; run `dbs qc rules --write`")
            return 1
        print(f"{target} up to date")
    else:
        print(text)
    return 0


def _cmd_run(args: argparse.Namespace) -> int:
    bundle = io.read(Path(args.stem))
    reference = io.read(Path(args.reference)) if args.reference else None
    results = run(bundle, load(Path(args.rules)), reference)
    for r in results:
        mark = {Status.PASS: "pass", Status.FAIL: "FAIL", Status.NOT_APPLICABLE: "n/a "}[r.status]
        print(f"{mark} {r.rule_id} {r.name:<36} [{r.severity}] {r.detail}")
    v = verdict(results)
    print(f"verdict: {v}")
    return 1 if v == "reject" else 0


def register(sub: argparse._SubParsersAction) -> None:  # type: ignore[type-arg]
    qc = sub.add_parser("qc", help="signal-quality and trial-acceptance rules")
    qsub = qc.add_subparsers(dest="qc_command", required=True)
    v = qsub.add_parser("validate", help="check rules against evaluators and the registry")
    v.add_argument("--rules", default=str(RULES))
    v.add_argument("--registry", default="registry")
    v.set_defaults(handler=_cmd_validate)
    r = qsub.add_parser("rules", help="render the rule table")
    r.add_argument("--rules", default=str(RULES))
    r.add_argument("--doc", default=str(SPEC_DOC))
    mode = r.add_mutually_exclusive_group()
    mode.add_argument("--write", action="store_true")
    mode.add_argument("--check", action="store_true")
    r.set_defaults(handler=_cmd_rules)
    run_p = qsub.add_parser("run", help="evaluate all applicable rules on a bundle")
    run_p.add_argument("stem")
    run_p.add_argument("--reference", default=None, help="reference bundle for QC-S08")
    run_p.add_argument("--rules", default=str(RULES))
    run_p.set_defaults(handler=_cmd_run)
